// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title AmanitaRegistry
 * @dev Универсальный on-chain-реестр адресов контрактов экосистемы Amanita.
 */
contract AmanitaRegistry {
    address public owner;

    mapping(string => address) private addresses;
    string[] private contractNames; // список всех имён (ключей)

    event AddressUpdated(string indexed name, address indexed newAddress);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "AmanitaRegistry: not owner");
        _;
    }

    /**
     * @notice Добавить или обновить адрес контракта.
     * @param name Человеко-читаемое имя (например, "InviteNFT")
     * @param newAddress Новый адрес контракта.
     */
    function setAddress(string calldata name, address newAddress) external onlyOwner {
        require(newAddress != address(0), "AmanitaRegistry: zero address");

        // Если это новый ключ, сохраняем имя в массив
        if (addresses[name] == address(0)) {
            contractNames.push(name);
        }

        addresses[name] = newAddress;
        emit AddressUpdated(name, newAddress);
    }

    /**
     * @notice Получить адрес контракта по имени.
     * @param name Имя контракта.
     */
    function getAddress(string calldata name) external view returns (address) {
        return addresses[name];
    }

    /**
     * @notice Получить список всех имён контрактов, зарегистрированных в реестре.
     * @return Список имён (ключей).
     */
    function getAllContractNames() external view returns (string[] memory) {
        return contractNames;
    }

    /**
     * @notice Передать права управления (новому owner).
     * @param newOwner Новый адрес владельца.
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "AmanitaRegistry: zero address");
        owner = newOwner;
    }
}

contracts/AmanitaToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract AmanitaToken is ERC20, AccessControl {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");

    uint256 public constant INITIAL_SUPPLY = 888_888_888 ether;

    constructor(address owner) ERC20("Amanita", "AMANITA") {
        _mint(owner, INITIAL_SUPPLY);
        _grantRole(DEFAULT_ADMIN_ROLE, owner);
        _grantRole(MINTER_ROLE, owner);
    }

    function decimals() public view virtual override returns (uint8) {
        return 18;
    }

    function mint(address to, uint256 amount) external onlyRole(MINTER_ROLE) {
        _mint(to, amount);
    }

    function burn(address from, uint256 amount) external onlyRole(MINTER_ROLE) {
        _burn(from, amount);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/InviteNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

contract InviteNFT is ERC721, AccessControl {
    uint256 private _tokenIdCounter;

    // Роль продавца для доступа к минтингу инвайтов
    bytes32 public constant SELLER_ROLE = keccak256("SELLER_ROLE");

    // Маппинг: inviteCode (уникальный строковый код) => tokenId (NFT инвайта)
    // Позволяет быстро найти NFT по коду, который вводит пользователь
    mapping(string => uint256) public inviteCodeToTokenId;

    // Маппинг: tokenId (NFT инвайта) => inviteCode (уникальный строковый код)
    // Для обратного поиска inviteCode по tokenId (например, для отображения или аудита)
    mapping(uint256 => string) public tokenIdToInviteCode;

    // Маппинг: tokenId => использован ли инвайт
    // Гарантирует, что каждый инвайт может быть использован только один раз
    mapping(uint256 => bool) public isInviteUsed;

    // Маппинг: user (адрес) => использованный инвайт (tokenId)
    // Не позволяет одному пользователю использовать более одного инвайта
    mapping(address => uint256) public usedInviteByUser;

    // Маппинг: tokenId => срок действия инвайта (timestamp, 0 если бессрочный)
    // Позволяет делать инвайты временными (например, для акций)
    mapping(uint256 => uint256) public inviteExpiry;

    // Маппинг: tokenId => дата создания инвайта (timestamp)
    // Для аудита, статистики, отслеживания «свежести» инвайтов
    mapping(uint256 => uint256) public inviteCreatedAt;

    // Маппинг: tokenId => адрес создателя (minter)
    // Позволяет отслеживать, кто создал инвайт (например, продавец или админ)
    mapping(uint256 => address) public inviteMinter;

    // Маппинг: tokenId => адрес первого владельца инвайта
    // Для построения реферальных деревьев, аудита, статистики
    mapping(uint256 => address) public inviteFirstOwner;

    // Маппинг: user (адрес) => список всех его инвайтов (tokenId)
    // Быстрый доступ ко всем инвайтам пользователя (для личного кабинета, управления, аналитики)
    mapping(address => uint256[]) public userInvites;

    // Счётчик общего количества использованных инвайтов
    // Для мониторинга, лимитов, аналитики, контроля эмиссии
    uint256 public totalInvitesUsed;

    // Счётчик общего количества выданных инвайтов
    // Для мониторинга, лимитов, аналитики, контроля эмиссии
    uint256 public totalInvitesMinted;

    // Маппинг: tokenId => история всех владельцев (адреса)
    // Позволяет вести полный аудит всех передач инвайта (NFT) по времени
    mapping(uint256 => address[]) public inviteTransferHistory;

    // Массив всех активированных пользователей
    address[] public activatedUsers;

    // Маппинг: user (адрес) => количество заминченных инвайтов для этого пользователя
    mapping(address => uint256) public userInviteCount;

    event InviteActivated(address indexed user, string inviteCode, uint256 tokenId, uint256 timestamp);
    event BatchInvitesMinted(address indexed to, uint256[] tokenIds, string[] inviteCodes, uint256 expiry);
    event InviteTransferred(uint256 indexed tokenId, address from, address to, uint256 timestamp);

    constructor() ERC721("Amanita Invite", "AINV") {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /**
     * @dev Внутренняя проверка валидности инвайта по inviteCode и адресу пользователя
     * @param inviteCode inviteCode (строка)
     * @return success true если инвайт валиден, false иначе
     * @return reason строка с причиной невалидности ("not_found", "already_used", "expired", "user_already_activated")
     *
     * Критерии приёмки:
     * - inviteCode существует
     * - invite не использован
     * - invite не истёк
     * - Возвращает (true, "") если всё валидно, иначе (false, причина)
     * - Только internal view
     */
    function _validateInviteCode(string memory inviteCode) internal view returns (bool, string memory) {
        // 1. Получить tokenId по inviteCode
        uint256 tokenId = inviteCodeToTokenId[inviteCode];
        // 2. Проверка существования инвайта
        if (tokenId == 0) {
            return (false, "not_found");
        }
        // 3. Проверка, был ли инвайт уже использован
        if (isInviteUsed[tokenId]) {
            return (false, "already_used");
        }
        // 4. Проверка срока действия (если не бессрочный)
        uint256 expiry = inviteExpiry[tokenId];
        if (expiry != 0 && expiry < block.timestamp) {
            return (false, "expired");
        }
        // 5. Все проверки пройдены — инвайт валиден
        return (true, "");
    }

    function _validateInviteCode(string memory inviteCode, address user) internal view returns (bool, string memory) {
        if (usedInviteByUser[user] != 0) {
            return (false, "user_already_activated");
        }
        (bool valid, string memory reason) = _validateInviteCode(inviteCode);
        if (!valid) {
            return (false, reason);
        }
        return (true, "");
    }

    /**
     * @dev Проверка валидности инвайта по inviteCode и адресу пользователя
     * @param inviteCode inviteCode (строка)
     * @return success true если инвайт валиден, false иначе
     * @return reason строка с причиной невалидности ("not_found", "already_used", "expired", "user_already_activated")
     * 
     */
    function validateInviteCode(string memory inviteCode) public view returns (bool, string memory) {
        return _validateInviteCode(inviteCode);
    }

    /**
     * @dev Активация инвайта и batch-минт новых инвайтов для пользователя
     * @param inviteCode код инвайта, который активируется (строка)
     * @param user адрес пользователя, который активирует инвайт
     * @param newInviteCodes массив новых inviteCode для раздачи друзьям
     * @param expiry срок действия новых инвайтов (timestamp, 0 если бессрочные)
     *
     * Критерии приёмки:
     * - Все проверки валидности и уникальности до изменения состояния
     * - inviteCode валиден, не использован, не истёк, user не активирован
     * - inviteCode отмечается как использованный, user добавляется в историю
     * - Минтятся новые инвайты на user, все маппинги инициализированы
     * - Эмитятся события InviteActivated и BatchInvitesMinted
     * - Счётчики обновляются
     * - Метод доступен только авторизованным (например, MINTER_ROLE)
     * - Любая ошибка — revert всей транзакции
     */
    function activateAndMintInvites(
        string memory inviteCode,
        address user,
        string[] memory newInviteCodes,
        uint256 expiry
    ) external onlyRole(SELLER_ROLE) {
        // 1. Проверка, что пользователь не активировал инвайт ранее
        require(usedInviteByUser[user] == 0, "User already activated invite");
        // 2. Проверка валидности inviteCode и expiry
        (bool valid, string memory reason) = _validateInviteCode(inviteCode, user);
        require(valid, reason);
        uint256 tokenId = inviteCodeToTokenId[inviteCode];
        // 3. Проверка уникальности newInviteCodes внутри массива
        uint256 len = newInviteCodes.length;
        for (uint256 i = 0; i < len; i++) {
            for (uint256 j = i + 1; j < len; j++) {
                require(keccak256(bytes(newInviteCodes[i])) != keccak256(bytes(newInviteCodes[j])), "Duplicate newInviteCode in batch");
            }
        }
        // 4. Проверка уникальности каждого newInviteCode в системе
        for (uint256 i = 0; i < len; i++) {
            require(inviteCodeToTokenId[newInviteCodes[i]] == 0, "New invite code already exists");
        }
        // 5. Отметить inviteCode как использованный
        isInviteUsed[tokenId] = true;
        usedInviteByUser[user] = tokenId;
        inviteTransferHistory[tokenId].push(user);
        totalInvitesUsed += 1;
        // Добавить пользователя в список активированных
        activatedUsers.push(user);
        emit InviteActivated(user, inviteCode, tokenId, block.timestamp);
        // 6. Минт новых инвайтов для user
        require(newInviteCodes.length == 12, "Must mint exactly 12 invites");
        uint256[] memory tokenIds = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            string memory code = newInviteCodes[i];
            tokenIds[i] = _mintInvite(code, user, expiry);
        }
        totalInvitesMinted += len;
        // Обновляем счетчик инвайтов пользователя
        userInviteCount[user] = len;
        emit BatchInvitesMinted(user, tokenIds, newInviteCodes, expiry);
    }

    /**
     * @dev Получить tokenId по inviteCode
     * @param inviteCode inviteCode (строка)
     * @return tokenId идентификатор NFT инвайта
     */
    function getTokenIdByInviteCode(string memory inviteCode) public view returns (uint256) {
        return inviteCodeToTokenId[inviteCode];
    }

    /**
     * @dev Получить inviteCode по tokenId
     * @param tokenId идентификатор NFT инвайта
     * @return inviteCode inviteCode (строка)
     */
    function getInviteCodeByTokenId(uint256 tokenId) public view returns (string memory) {
        return tokenIdToInviteCode[tokenId];
    }

    /**
     * @dev Получить историю всех владельцев инвайта (NFT)
     * @param tokenId идентификатор NFT инвайта
     * @return owners массив адресов всех владельцев по порядку
     *
     * Критерии приёмки:
     * - Принимает tokenId
     * - Возвращает inviteTransferHistory[tokenId]
     * - Не изменяет состояние
     * - Может быть вызван любым участником
     * - revert, если tokenId не существует (для UX)
     */
    function getInviteTransferHistory(uint256 tokenId) public view returns (address[] memory) {
        return inviteTransferHistory[tokenId];
    }

    /**
     * @dev Получить все инвайты пользователя
     * @param user адрес пользователя
     * @return tokenIds массив всех tokenId, которыми владел пользователь
     *
     * Критерии приёмки:
     * - Принимает адрес пользователя
     * - Возвращает userInvites[user]
     * - Не изменяет состояние
     * - Может быть вызван любым участником
     */
    function getUserInvites(address user) public view returns (uint256[] memory) {
        return userInvites[user];
    }

    /**
     * @dev Проверить, был ли использован инвайт
     * @param tokenId идентификатор NFT инвайта
     * @return true если использован, false если нет
     */
    function isInviteTokenUsed(uint256 tokenId) public view returns (bool) {
        return isInviteUsed[tokenId];
    }

    /**
     * @dev Получить дату создания инвайта
     * @param tokenId идентификатор NFT инвайта
     * @return timestamp дата создания (timestamp)
     */
    function getInviteCreatedAt(uint256 tokenId) public view returns (uint256) {
        return inviteCreatedAt[tokenId];
    }

    /**
     * @dev Получить срок действия инвайта
     * @param tokenId идентификатор NFT инвайта
     * @return expiry срок действия (timestamp, 0 если бессрочный)
     */
    function getInviteExpiry(uint256 tokenId) public view returns (uint256) {
        return inviteExpiry[tokenId];
    }

    /**
     * @dev Получить адрес минтера инвайта
     * @param tokenId идентификатор NFT инвайта
     * @return minter адрес минтера
     */
    function getInviteMinter(uint256 tokenId) public view returns (address) {
        return inviteMinter[tokenId];
    }

    /**
     * @dev Получить первого владельца инвайта
     * @param tokenId идентификатор NFT инвайта
     * @return owner адрес первого владельца
     */
    function getInviteFirstOwner(uint256 tokenId) public view returns (address) {
        return inviteFirstOwner[tokenId];
    }

    /**
     * @dev Проверка, активирован ли пользователь
     * @param user адрес пользователя
     * @return bool true если пользователь активирован, false иначе
     */
    function isUserActivated(address user) public view returns (bool) {
        return usedInviteByUser[user] != 0;
    }

    /**
     * @dev Проверить валидность массива inviteCodes для пользователя user (batch-валидация)
     * @param inviteCodes массив inviteCode для проверки
     * @param user адрес пользователя
     * @return success массив результатов проверки валидности
     * @return reasons массив строк с причинами невалидности
     *
     * Алгоритм:
     * 1. Для каждого inviteCode вызвать validateInviteCode(inviteCode, user)
     * 2. Сохранить результат success и reason в отдельные массивы
     * 3. Вернуть оба массива
     */
    function batchValidateInviteCodes(string[] memory inviteCodes, address user) public view returns (bool[] memory, string[] memory) {
        uint256 len = inviteCodes.length;
        bool[] memory success = new bool[](len);
        string[] memory reasons = new string[](len);
        for (uint256 i = 0; i < len; i++) {
            (bool ok, string memory reason) = _validateInviteCode(inviteCodes[i], user);
            success[i] = ok;
            reasons[i] = reason;
        }
        return (success, reasons);
    }

    /**
     * @dev Получить все активированные пользователи
     * @return users массив адресов всех активированных пользователей
     *
     * Критерии приёмки:
     * - Возвращает массив всех адресов, у которых usedInviteByUser[address] != 0
     * - Не изменяет состояние
     * - Может быть вызван любым участником
     */
    function getAllActivatedUsers() public view returns (address[] memory) {
        return activatedUsers;
    }

    /**
     * @dev Batch-минт новых инвайтов (NFT) с inviteCodes и сроком действия expiry для раздачи стартовой аудитории.
     * @param inviteCodes массив уникальных inviteCode, которые будут заминчены
     * @param expiry срок действия (timestamp, 0 если бессрочный)
     *
     * Доступ: только адреса с ролью SELLER_ROLE.
     * Минт всегда идёт на msg.sender (селлера), без лимитов на количество batch-ей и размер batch-а.
     */
    function mintInvites(string[] calldata inviteCodes, uint256 expiry) external onlyRole(SELLER_ROLE) {
        uint256 len = inviteCodes.length;
        require(len > 0, "No invite codes provided");
        // Проверка срока действия
        require(expiry == 0 || expiry > block.timestamp, "Expiry must be 0 or in the future");
        // Проверка уникальности inviteCodes внутри массива
        for (uint256 i = 0; i < len; i++) {
            for (uint256 j = i + 1; j < len; j++) {
                require(keccak256(bytes(inviteCodes[i])) != keccak256(bytes(inviteCodes[j])), "Duplicate inviteCode in batch");
            }
        }
        uint256[] memory tokenIds = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            tokenIds[i] = _mintInvite(inviteCodes[i], msg.sender, expiry);
        }
        totalInvitesMinted += len;
        emit BatchInvitesMinted(msg.sender, tokenIds, inviteCodes, expiry);
    }

    /**
     * @dev Внутренний метод для минтинга одного инвайта (NFT)
     * @param inviteCode уникальный inviteCode
     * @param to адрес получателя
     * @param expiry срок действия (timestamp, 0 если бессрочный)
     * @return tokenId идентификатор заминченного NFT
     *
     * Критерии приёмки:
     * - inviteCode уникален (inviteCodeToTokenId[inviteCode] == 0)
     * - Генерируется новый tokenId
     * - NFT минтится на адрес to
     * - Все маппинги корректно инициализированы
     * - tokenId добавляется в userInvites[to] и inviteTransferHistory[tokenId]
     * - Возвращается новый tokenId
     * - Только internal
     */
    function _mintInvite(string memory inviteCode, address to, uint256 expiry) internal returns (uint256) {
        require(inviteCodeToTokenId[inviteCode] == 0, "Invite code already exists");
        _tokenIdCounter++;
        uint256 tokenId = _tokenIdCounter;
        _safeMint(to, tokenId);
        inviteCodeToTokenId[inviteCode] = tokenId;
        tokenIdToInviteCode[tokenId] = inviteCode;
        inviteExpiry[tokenId] = expiry;
        inviteCreatedAt[tokenId] = block.timestamp;
        inviteMinter[tokenId] = msg.sender;
        inviteFirstOwner[tokenId] = to;
        userInvites[to].push(tokenId);
        inviteTransferHistory[tokenId].push(to);
        // Увеличиваем счетчик инвайтов пользователя
        userInviteCount[to] += 1;
        return tokenId;
    }

    /**
     * @dev Внутреннее обновление статуса инвайта и пользователя при активации
     * @param tokenId идентификатор инвайта
     * @param user адрес пользователя
     *
     * Критерии приёмки:
     * - isInviteUsed[tokenId] = true
     * - usedInviteByUser[user] = tokenId
     * - inviteTransferHistory[tokenId].push(user)
     * - totalInvitesUsed увеличивается на 1
     * - Только internal
     * - Не эмитит события
     */
    function _updateInviteStatus(uint256 tokenId, address user) internal {
        isInviteUsed[tokenId] = true;
        usedInviteByUser[user] = tokenId;
        inviteTransferHistory[tokenId].push(user);
        totalInvitesUsed += 1;
    }

    /**
     * @dev Назначить адрес продавцом (SELLER_ROLE)
     * @param seller адрес продавца
     */
    function addSeller(address seller) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _grantRole(SELLER_ROLE, seller);
    }

    /**
     * @dev Убрать роль продавца у адреса
     * @param seller адрес продавца
     */
    function removeSeller(address seller) external onlyRole(DEFAULT_ADMIN_ROLE) {
        _revokeRole(SELLER_ROLE, seller);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    function _update(address to, uint256 tokenId, address auth) internal virtual override returns (address) {
        address from = _ownerOf(tokenId);

        // Разрешаем только минт (from == address(0)) и сжигание (to == address(0))
        require(from == address(0) || to == address(0), "InviteNFT: soulbound");

        return super._update(to, tokenId, auth);
    }

    function isSeller(address user) public view returns (bool) {
        return hasRole(SELLER_ROLE, user);
    }
}

contracts/LoveDoPostNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/structs/EnumerableSet.sol";

/**
 * @title LoveDoPostNFT
 * @dev NFT-контракт для LoveDo постов в системе Amanita. Позволяет пользователям создавать отзывы-признания
 * для продавцов, на которые продавцы могут ставить суперлайки. Каждый суперлайк становится основой для эмиссии $AMANITA_GOV.
 */
contract LoveDoPostNFT is ERC721URIStorage, AccessControl {
    using EnumerableSet for EnumerableSet.UintSet;

    // --- Roles ---
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Структура одного LoveDo поста
    struct LoveDo {
        address author;          // пользователь, написавший пост
        address sellerTo;        // продавец, которому посвящён пост
        address linkedSeller;    // селлер, пригласивший автора
        uint8 superlikes;        // количество суперлайков
        uint256 timestamp;       // когда был создан пост, чтобы анализировать динамику и избегать манипуляций через старые посты
    }

    /// @notice Карта tokenId → LoveDo метаданные
    mapping(uint256 => LoveDo) public loveDos;

    /// @notice Массив tokenId всех постов, направленных на конкретного селлера
    mapping(address => uint256[]) private postsBySeller;


    /// @notice Мапа для суперлайков: tokenId => seller => liked
    mapping(uint256 => mapping(address => bool)) public hasSuperliked;

    /// @notice Отслеживание суперлайков по селлеру за месяц
    mapping(address => mapping(uint256 => uint8)) public monthlyLikesUsed;

    /// @notice Счётчик токенов
    uint256 public nextTokenId;

    /// @notice Лимит постов на одного участника
    uint8 public constant MAX_MONTHLY_POSTS_PER_USER = 8;

    /// @notice Сколько постов пользователь сделал за месяц
    mapping(address => mapping(uint256 => uint8)) public postsPerUserPerMonth;

    /// @notice Макс. LoveDo постов, в которых может быть упомянут один селлер
    uint8 public constant MAX_MENTIONS_PER_SELLER = 8;

    /// @notice Сколько раз каждый селлер уже был упомянут
    mapping(address => uint8) public mentionsOf;

    /// @notice Мапа: кто сколько постов уже создал
    mapping(address => uint8) public postsMintedBy;

    /// @notice Мапа: чтобы анализировать поведение аудитории.
    mapping(address => uint256[]) public superlikedPostsByUser;

    /// @notice Событие минта нового поста
    event LoveDoMinted(uint256 indexed tokenId, address indexed author, address indexed sellerTo);

    /// @notice Событие суперлайка
    event Superliked(uint256 indexed tokenId, address indexed bySeller, uint8 newTotal);

    /// @notice Ссылка на внешний контракт InviteNFT, реализующий граф инвайтов
    IInviteGraph public inviteGraph;

    /// @notice Мапа: Защита от фронтраннига
    mapping(address => uint256) public superlikeNonces;


    /// @notice Ссылка на AmanitaRegistry для проверки SELLER роли
    IAmanitaRegistry public amanitaRegistry;

    /// @notice Лимит суперлайков, которые пользователь может поставить за месяц
    uint8 public constant MAX_SUPERLIKES_PER_MONTH = 8;

    constructor(address _admin, address _inviteGraph, address _amanitaRegistry)
        ERC721("LoveDoPost", "LDP")
    {
        require(_admin != address(0), "Admin required");
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);
        inviteGraph = IInviteGraph(_inviteGraph);
        amanitaRegistry = IAmanitaRegistry(_amanitaRegistry);
    }

    /**
     * @notice Создание LoveDo поста
     * @param sellerTo Продавец, которому адресован пост
     * @param uri Ссылка на IPFS метаданные (отзыв)
     */
    function mintLoveDoPost(address sellerTo, string calldata uri) external {
        uint256 currentMonth = block.timestamp / 30 days;
        require(
            postsPerUserPerMonth[msg.sender][currentMonth] < MAX_MONTHLY_POSTS_PER_USER,
            "Monthly post limit reached"
        );

        address linkedSeller = inviteGraph.getInviterOf(msg.sender);
        require(linkedSeller != address(0), "User is not invited");
        require(sellerTo != msg.sender, "Cannot post to self");
        require(mentionsOf[sellerTo] < MAX_MENTIONS_PER_SELLER, "Seller mention limit reached");

        uint256 tokenId = nextTokenId++;
        postsBySeller[sellerTo].push(tokenId);
        _safeMint(msg.sender, tokenId);
        _setTokenURI(tokenId, uri);

        loveDos[tokenId] = LoveDo({
            author: msg.sender,
            sellerTo: sellerTo,
            linkedSeller: linkedSeller,
            superlikes: 0,
            timestamp: block.timestamp
        });

        postsPerUserPerMonth[msg.sender][currentMonth]++;
        mentionsOf[sellerTo]++;
        emit LoveDoMinted(tokenId, msg.sender, sellerTo);
    }

    /**
    * @notice Возвращает все LoveDo tokenId, где указанный селлер был целью поста
    * @param seller Адрес селлера
    * @return tokenIds Массив ID постов
    */
    function getLoveDoMentions(address seller) external view returns (uint256[] memory tokenIds) {
        return postsBySeller[seller];
    }


    function getRemainingMentionsForSeller(address seller) external view returns (uint8) {
        return MAX_MENTIONS_PER_SELLER - mentionsOf[seller];
    }

    function getRemainingPostsThisMonth(address user) external view returns (uint8) {
        uint256 currentMonth = block.timestamp / 30 days;
        return MAX_MONTHLY_POSTS_PER_USER - postsPerUserPerMonth[user][currentMonth];
    }


    /**
     * @notice Суперлайк от селлера на пост своей аудитории
     * @param tokenId ID поста
     */
    function addSuperlike(uint256 tokenId, uint256 expectedNonce) external {

        uint256 monthKey = block.timestamp / 30 days;
        require(monthlyLikesUsed[msg.sender][monthKey] < MAX_SUPERLIKES_PER_MONTH, "Monthly superlikes exhausted");

        // --- [0] Проверяем nonce
        require(superlikeNonces[msg.sender] == expectedNonce, "Invalid nonce");
        superlikeNonces[msg.sender]++;

        // --- [1] Проверяем, существует ли пост по указанному tokenId
        require(postExists(tokenId), "LoveDo: post does not exist");
        // Безопасность: не позволяем ставить лайк в несуществующий пост

        LoveDo storage post = loveDos[tokenId];

        // --- [2] Проверяем, не ставил ли этот адрес лайк уже ранее
        require(!hasSuperliked[tokenId][msg.sender], "LoveDo: already superliked");
        // Безопасность: один адрес может суперлайкнуть пост только один раз

        // --- [3] Запрещаем авторам лайкать свои собственные посты
        require(msg.sender != loveDos[tokenId].author, "LoveDo: cannot superlike own post");
        // Безопасность: предотвращает self-like и инфляцию

        // --- [4] Получаем адрес селлера, который пригласил автора поста
        address inviterOfAuthor = inviteGraph.invitedBy(loveDos[tokenId].author);
        require(inviterOfAuthor != address(0), "LoveDo: author not invited");
        // Защита: автор должен быть реально кем-то приглашён

        // --- [5] Получаем адрес инвайтера для лайкера и сравниваем с автором
        address inviterOfLiker = inviteGraph.invitedBy(msg.sender);
        require(inviterOfLiker == inviterOfAuthor, "LoveDo: liker not in same circle");
        // Социальная модель: суперлайк могут ставить только участники,
        // приглашённые тем же селлером — "горизонтальные связи доверия"

        // --- [6] Проверяем, что получатель (селлер) официально зарегистрирован
        require(amanitaRegistry.hasSellerRole(loveDos[tokenId].sellerTo), "LoveDo: target seller not registered");
        loveDos[tokenId].superlikes += 1;
        hasSuperliked[tokenId][msg.sender] = true;
        monthlyLikesUsed[msg.sender][monthKey]++;
        superlikedPostsByUser[msg.sender].push(tokenId);
        emit Superliked(tokenId, msg.sender, loveDos[tokenId].superlikes);
    }

    function getLoveDoCount(address seller) external view returns (uint8) {
        return uint8(postsBySeller[seller].length);
    }

    // --- View Getters ---

    function getPost(uint256 tokenId) external view returns (LoveDo memory) {
        require(postExists(tokenId), "Invalid post");
        return loveDos[tokenId];
    }

    function getSuperlikes(uint256 tokenId) external view returns (uint8) {
        return loveDos[tokenId].superlikes;
    }

    function getRemainingSuperlikes(address user) external view returns (uint8) {
        uint256 monthKey = block.timestamp / 30 days;
        return MAX_SUPERLIKES_PER_MONTH - monthlyLikesUsed[user][monthKey];
    }

    // --- Admin ---

    function setInviteGraph(address newGraph) external onlyRole(ADMIN_ROLE) {
        inviteGraph = IInviteGraph(newGraph);
    }

    function setAmanitaRegistry(address newRegistry) external onlyRole(ADMIN_ROLE) {
        amanitaRegistry = IAmanitaRegistry(newRegistry);
    }

    function postExists(uint256 tokenId) public view returns (bool) {
        // Если есть владелец, то пост существует
        return ownerOf(tokenId) != address(0);
    }

    // Обязательный override для поддержки интерфейсов (множественное наследование)
    function supportsInterface(bytes4 interfaceId) public view override(ERC721URIStorage, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}


/// @notice Интерфейс для InviteNFT или InviteGraph контракта
interface IInviteGraph {
    function getInviterOf(address user) external view returns (address);
    function invitedBy(address user) external view returns (address);
}

/// @notice Интерфейс для AmanitaRegistry
interface IAmanitaRegistry {
    function hasSellerRole(address user) external view returns (bool);
}

contracts/LoveEmissionEngine.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./LoveDoPostNFT.sol";
import "./AmanitaToken.sol";
import "./AmanitaGovToken.sol";
import "./InviteNFT.sol";

/**
 * @title LoveEmissionEngine
 * @dev Контракт эмиссии для Loveconomy: минтит $AMANITA (утилити) и $AGOV (голос)
 * на основе суперлайков в LoveDoPostNFT.
 */
contract LoveEmissionEngine is AccessControl {
    bytes32 public constant EMITTER_ROLE = keccak256("EMITTER_ROLE");
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

    /// @notice Токены
    IERC20 public immutable amanitaToken;
    IAGovToken public immutable agovToken;
    ILoveDoPostNFT public immutable loveDo;
    IInviteGraph public inviteGraph;
    mapping(address => uint256) public amanitaAccrued;

    /// @notice Сколько накоплено AGOV, но не получено
    mapping(address => uint256) public agovAccrued;

    /// @notice Коэффициент эмиссии (на 1 суперлайк)
    uint256 public constant EMISSION_RATE = 1 ether;

    /// @notice События
    event Emission(address indexed seller, uint256 amanitaAmount, uint256 agovAccrued);
    event AGOVClaimed(address indexed seller, uint256 amount);
    event ClaimedAMANITA(address indexed seller, uint256 amount);
    event ClaimedAGOV(address indexed seller, uint256 amount);

    mapping(address => bool) public agovClaimed;
    uint8 public constant LOVE_DO_THRESHOLD = 8;

    constructor(
        address _amanita,
        address _agov,
        address _loveDo,
        address _inviteGraph,
        address _admin
    ) {
        require(_admin != address(0), "admin required");

        amanitaToken = IERC20(_amanita);
        agovToken = IAGovToken(_agov);
        loveDo = ILoveDoPostNFT(_loveDo);
        inviteGraph = IInviteGraph(_inviteGraph);

        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _grantRole(ADMIN_ROLE, _admin);
    }

    function emitForSuperlike(uint256 tokenId, address liker) external onlyRole(EMITTER_ROLE) {
        (address author, address sellerTo, address linkedSeller, uint8 superlikes) = loveDo.getPost(tokenId);

        address inviterOfAuthor = inviteGraph.invitedBy(author);
        address inviterOfLiker = inviteGraph.invitedBy(liker);

        require(inviterOfAuthor != address(0), "Post author not invited");
        require(inviterOfAuthor == inviterOfLiker, "Liker must be from same inviter group");
        require(liker != author, "Author can't like their own post");

        // 1. Записать superlike
        bool success = loveDo.addSuperlike(tokenId);
        require(success, "Superlike failed");

        // 2. Начислить накопленные токены
        amanitaAccrued[sellerTo] += EMISSION_RATE;
        agovAccrued[sellerTo] += EMISSION_RATE;

        emit Emission(sellerTo, EMISSION_RATE, agovAccrued[sellerTo]);
    }

    /**
    * @notice Позволяет селлеру забрать накопленные $AMANITA (утилити токены)
    * @dev Вызывается вручную, чтобы избежать газовых затрат при каждом суперлайке
    */
    function claimAMANITA() external {
        uint256 amount = amanitaAccrued[msg.sender];
        require(amount > 0, "LoveEmission: nothing to claim");

        // Обнуляем до трансфера — защита от reentrancy
        amanitaAccrued[msg.sender] = 0;

        bool success = amanitaToken.transfer(msg.sender, amount);
        require(success, "LoveEmission: transfer failed");

        emit ClaimedAMANITA(msg.sender, amount);
    }

    /**
    * @notice Позволяет селлеру активировать $AGOV, если он заслужил репутацию (≥ 8 постов)
    * @dev $AGOV становится "реальным" governance-токеном только после подтверждённой репутации
    */
    function claimAGOV() external {
        require(!agovClaimed[msg.sender], "LoveEmission: already claimed");

        uint8 count = loveDo.getLoveDoCount(msg.sender);
        require(count >= LOVE_DO_THRESHOLD, "LoveEmission: not enough LoveDo posts");

        uint256 amount = agovAccrued[msg.sender];
        require(amount > 0, "LoveEmission: nothing to mint");

        agovAccrued[msg.sender] = 0;
        agovClaimed[msg.sender] = true;

        agovToken.mint(msg.sender, amount);

        emit ClaimedAGOV(msg.sender, amount);
    }

    /**
    * @notice Возвращает текущее состояние репутации селлера
    * @param seller Адрес селлера, чью репутацию проверяем
    * @return pending Количество накопленных, но ещё не активированных $AGOV
    * @return active Баланс уже заминченных $AGOV
    * @return loveDoCount Количество LoveDo постов в его пользу
    */
    function getReputationProgress(address seller) external view returns (
        uint256 pending,
        uint256 active,
        uint8 loveDoCount
    ) {
        // Накопленные, но ещё не активированные $AGOV
        pending = agovAccrued[seller];

        // Если уже был claim, репутация активна
        active = agovClaimed[seller] ? agovToken.balanceOf(seller) : 0;

        // Количество LoveDo постов, направленных на этого селлера
        loveDoCount = loveDo.getLoveDoCount(seller);
    }
}

interface IAGovToken {
    function mint(address to, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

interface ILoveDoPostNFT {
    function mentionsOf(address seller) external view returns (uint8);

    function addSuperlike(uint256 tokenId) external returns (bool);

    function getPost(uint256 tokenId) external view returns (
        address author,
        address sellerTo,
        address linkedSeller,
        uint8 superlikes
    );

    function getLoveDoCount(address seller) external view returns (uint8);
}

contracts/Orders.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title Orders
 * @dev On-chain registry of Amanita protocol orders with IPFS metadata and OTP validation.
 */
contract Orders is AccessControl {
    /// @notice Role for marking orders as paid (assigned to the Payment Router)
    bytes32 public constant ROUTER_ROLE = keccak256("ROUTER_ROLE");

    /// @notice Order structure stored on-chain
    struct Order {
        address buyer;
        address seller;
        uint256 amount;
        string otp;
        string ipfsHash;
        bool paid;
    }

    /// @notice Mapping of order hash to Order data
    mapping(bytes32 => Order) private orders;

    /// @notice Emitted when a new order is registered
    event OrderCreated(
        bytes32 indexed orderHash,
        address indexed seller,
        address indexed buyer,
        uint256 amount,
        string otp,
        string ipfsHash
    );

    /// @notice Emitted when an order is marked as paid
    event OrderPaid(bytes32 indexed orderHash);

    /**
     * @dev Initializes the contract, assigning DEFAULT_ADMIN_ROLE to the deployer.
     */
    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    /**
     * @notice Creates a new order and stores it on-chain.
     * @param buyer The buyer's wallet address.
     * @param seller The seller's wallet address.
     * @param amount Total order amount including OTP in decimal part.
     * @param otp Unique OTP string encoded in payment.
     * @param ipfsHash IPFS hash of the off-chain order metadata.
     * @return orderHash The keccak256 hash of the order.
     */
    function createOrder(
        address buyer,
        address seller,
        uint256 amount,
        string memory otp,
        string memory ipfsHash
    ) external returns (bytes32 orderHash) {
        orderHash = keccak256(abi.encodePacked(buyer, seller, amount, otp, ipfsHash));

        require(orders[orderHash].amount == 0, "OrderAlreadyExists");

        orders[orderHash] = Order({
            buyer: buyer,
            seller: seller,
            amount: amount,
            otp: otp,
            ipfsHash: ipfsHash,
            paid: false
        });

        emit OrderCreated(orderHash, seller, buyer, amount, otp, ipfsHash);
    }

    /**
     * @notice Marks a given order as paid.
     * @dev Can only be called by address with ROUTER_ROLE (e.g. Payment Router).
     * @param orderHash Hash of the order to mark as paid.
     */
    function markAsPaid(bytes32 orderHash) external onlyRole(ROUTER_ROLE) {
        Order storage o = orders[orderHash];

        require(o.amount != 0, "OrderNotFound");
        require(!o.paid, "OrderAlreadyPaid");

        o.paid = true;

        emit OrderPaid(orderHash);
    }

    /**
     * @notice Returns full order data for a given order hash.
     * @param orderHash The hash of the order.
     * @return o The Order struct.
     */
    function getOrder(bytes32 orderHash) external view returns (Order memory o) {
        o = orders[orderHash];
        require(o.amount != 0, "OrderNotFound");
    }
}

contracts/ProductRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title ProductRegistry
 * @dev Хранит реестр товаров для децентрализованного маркетплейса Amanita.
 * - Хранит только ссылку (ipfsCID) на JSON-метаданные товара.
 * - Не хранит фото и большие данные on-chain (экономия газа).
 * - Продавцы могут создавать, обновлять, деактивировать свои товары.
 * - Другие пользователи могут читать товары.
 * - Все запросы читаемые (view), минимальный газ.
 */
interface IInviteNFT {
    function isUserActivated(address user) external view returns (bool);
    function isSeller(address user) external view returns (bool);
}

contract ProductRegistry {
    /// @notice Структура товара
    struct Product {
        uint256 id;          // Уникальный идентификатор товара
        address seller;      // Продавец (автор записи)
        string ipfsCID;      // Ссылка на JSON-описание (IPFS CID)
        bool active;         // Активен ли товар
    }

    /// @notice InviteNFT для проверки активации пользователя
    IInviteNFT public inviteNFT;

    /// @notice Конструктор
    /// @param _inviteNFT адрес контракта InviteNFT
    constructor(address _inviteNFT) {
        require(_inviteNFT != address(0), "Invalid InviteNFT address");
        inviteNFT = IInviteNFT(_inviteNFT);
    }

    // Версия каталога продавца
    mapping(address => uint256) public catalogVersion;

    /// @notice Маппинг: productId => Product
    mapping(uint256 => Product) private products;

    /// @notice Счётчик всех товаров (для генерации id)
    uint256 private _productIdCounter;

    /// @notice Маппинг: продавец => список всех productId
    /// Это помогает быстро получить товары продавца (экономия off-chain фильтра)
    mapping(address => uint256[]) private productsBySeller;

    /// @notice Список всех активных товаров (id)
    /// Можно вернуть список всех id для фронтенда — дешевле, чем Product[]
    uint256[] private activeProductIds;

    // --------------------------------
    // ------- События ---------------
    // --------------------------------

    /// @notice Событие: создан новый товар
    event ProductCreated(address indexed seller,
        uint256 productId,
        string ipfsCID,
        uint256 status);

    /// @notice Событие: обновлён товар
    event ProductUpdated(
        address indexed seller,
        uint256 productId,
        string ipfsCID,
        uint256 price,
        uint256 status
    );

    /// @notice Событие: товар деактивирован
    event ProductDeactivated(uint256 indexed productId);

    /// @notice Событие: обновлена версия каталога продавца
    event CatalogUpdated(address indexed seller, uint256 newVersion);

    // --------------------------------
    // ------- Модификаторы ----------
    // --------------------------------

    /**
     * @dev Проверка, что msg.sender — активированный пользователь (InviteNFT).
     */
    modifier onlyActivatedUser() {
        require(inviteNFT.isUserActivated(msg.sender), "Not activated in InviteNFT");
        _;
    }

    /**
     * @dev Проверка, что msg.sender — продавец указанного товара.
     * @param productId id товара
     */
    modifier onlyOwnSellerProduct(uint256 productId) {
        require(products[productId].seller == msg.sender, "Not product seller");
        _;
    }

    // --------------------------------
    // ------- Основные методы -------
    // --------------------------------

    /**
    * @notice Создать новый товар.
    * @dev
    * - Проверяет, что пользователь активирован (InviteNFT).
    * - Проверяет, что CID не пустой и цена > 0.
    * - Генерирует уникальный productId.
    * - Сохраняет товар в маппинг продуктов.
    * - Добавляет productId в общий список активных товаров и в индекс продавца.
    * - Эмиттирует событие ProductCreated для трекинга.
    *
    * Критерии приёмки:
    * - Пользователь активирован.
    * - CID не пустой.
    * - Цена > 0.
    * - Все индексы обновлены (activeProductIds, productsBySeller).
    * - Данные доступны через getProduct, getAllActiveProductIds и getProductsBySeller.
    * - Событие ProductCreated доступно для фронтенда.
    *
    * Эффективность газа:
    * - O(1) операции без циклов.
    * - Минимальные storage-записи (только 3 массива и 1 mapping).
    */
    function createProduct(string calldata ipfsCID) external {
        require(bytes(ipfsCID).length > 0, "ProductRegistry: empty CID");

        // Генерируем новый productId
        _productIdCounter += 1;
        uint256 newProductId = _productIdCounter;

        // Создаём продукт в памяти
        Product memory newProduct = Product({
            id: newProductId,
            seller: msg.sender,
            ipfsCID: ipfsCID,
            active: true
        });

        // Сохраняем в storage
        products[newProductId] = newProduct;

        // Добавляем productId в список активных товаров
        activeProductIds.push(newProductId);

        // Добавляем productId в индекс продавца
        productsBySeller[msg.sender].push(newProductId);

        // Эмитим событие для фронтенда
        emit ProductCreated(msg.sender, newProductId, ipfsCID, 1);

        catalogVersion[msg.sender] += 1;
        emit CatalogUpdated(msg.sender, catalogVersion[msg.sender]);
    }


    /**
    * @notice Обновить товар (ipfsCID или цену).
    * @dev
    * - Продавец может обновлять только свой товар.
    * - CID и цена должны быть валидными (не пустой и > 0).
    * - Обновления сохраняются в storage.
    * - Эмиттируется событие ProductUpdated.
    *
    * Acceptance criteria:
    * - Продавец = msg.sender (onlySeller)
    * - CID != пустой, цена > 0
    * - Товар активен (не обновляем архивные)
    * - Поля ipfsCID и price обновлены
    * - Эмиттирован ProductUpdated
    *
    * Gas-эффективность:
    * - Прямой доступ к storage (O(1))
    * - Нет циклов или лишних вычислений
    */
    function updateProduct(uint256 productId, string calldata newIpfsCID, uint256 newPrice) external onlyOwnSellerProduct(productId) {
        require(bytes(newIpfsCID).length > 0, "ProductRegistry: empty CID");
        require(newPrice > 0, "ProductRegistry: price must be > 0");

        Product storage product = products[productId];
        require(product.active, "ProductRegistry: product not active");

        product.ipfsCID = newIpfsCID;

        emit ProductUpdated(msg.sender, productId, newIpfsCID, newPrice, 1);

        catalogVersion[msg.sender] += 1;  // обновляем только для этого продавца
        emit CatalogUpdated(msg.sender, catalogVersion[msg.sender]);
    }

    /**
    * @notice Деактивировать товар (сделать его невидимым в каталоге).
    * @dev
    * - Продавец может деактивировать только свой товар.
    * - Товар должен быть активным.
    * - Статус `active = false`.
    * - Удаляет productId из списка активных товаров через swap-and-pop (газ-эффективно).
    * - Эмиттирует событие ProductDeactivated.
    *
    * Acceptance criteria:
    * - Проверка продавца (onlySeller)
    * - Проверка, что товар активен
    * - Обновлён статус в storage
    * - Удалён из массива активных
    * - Эмиттировано событие
    *
    * Газ-эффективность:
    * - O(n) поиск + O(1) удаление (swap-and-pop)
    * - Никаких лишних storage-переменных
    */
    function deactivateProduct(uint256 productId) external onlyOwnSellerProduct(productId) {
        Product storage product = products[productId];
        require(product.active, "ProductRegistry: already deactivated");

        product.active = false;

        // Удаляем productId из списка активных товаров (экономия газа через swap-and-pop)
        uint256 len = activeProductIds.length;
        for (uint256 i = 0; i < len; i++) {
            if (activeProductIds[i] == productId) {
                // Меняем местами с последним элементом и убираем
                activeProductIds[i] = activeProductIds[len - 1];
                activeProductIds.pop();
                break;
            }
        }

        emit ProductDeactivated(productId);

        catalogVersion[msg.sender] += 1;  // обновляем только для этого продавца
        emit CatalogUpdated(msg.sender, catalogVersion[msg.sender]);
    }


    // --------------------------------
    // ------- View функции ----------
    // --------------------------------

    /**
    * @notice Получить данные товара.
    * @dev
    * - Доступна любому (public view).
    * - Проверяет существование (product.id != 0).
    * - Возвращает полные данные: id, seller, ipfsCID, price, active.
    *
    * Acceptance criteria:
    * - Возвращает существующую структуру Product.
    * - Реверт, если товар не существует.
    *
    * Газ-эффективность:
    * - Только чтение (view).
    * - Никаких циклов или лишних storage-запросов.
    */
    function getProduct(uint256 productId) external view returns (Product memory) {
        Product memory product = products[productId];
        require(product.id != 0, "ProductRegistry: product does not exist");
        return product;
    }

    /**
    * @notice Получить список id всех активных товаров.
    * @dev
    * - Публичная view-функция.
    * - Отдаёт snapshot массива activeProductIds.
    * - Экономично по газу (только чтение, нет циклов).
    *
    * Acceptance criteria:
    * - Отдаёт все id активных товаров (актуально в момент запроса).
    * - Прозрачность — любой может получить каталог.
    *
    * Газ-эффективность:
    * - O(1) чтение ссылки на storage-массив (view → memory).
    * - Нет вычислений/фильтрации.
    */
    function getAllActiveProductIds() external view returns (uint256[] memory) {
        return activeProductIds;
    }

    /**
    * @notice Получить список id всех товаров продавца.
    * @dev
    * - Public view.
    * - Не фильтрует по active — возвращает все товары (для прозрачности и истории).
    * - Лёгкое, дешёвое по газу (view → memory).
    *
    * Acceptance criteria:
    * - Возвращает массив id всех товаров продавца.
    * - Прозрачность — любой может получить историю продаж.
    *
    * Газ-эффективность:
    * - O(1) чтение ссылки на storage-массив.
    * - Никаких вычислений внутри функции.
    */
    function getProductsBySeller(address seller) external view returns (uint256[] memory) {
        return productsBySeller[seller];
    }

    /**
    * @notice Получить версию каталога продавца.
    * @dev
    * - Public view.
    * - Возвращает текущую версию каталога номер которой увеличивается при каждом 
    * обновлении или добавлении любого товара.
    *
    */
    function getMyCatalogVersion() external view returns (uint256) {
        require(inviteNFT.isSeller(msg.sender), "Not a seller");
        return catalogVersion[msg.sender];
    }

    /**
    * @notice Получить все товары продавца вместе со структурой Product.
    * @dev
    * - Public view.
    * - Возвращает все товары продавца.
    *
    */
    /**
    * @notice Получить все товары продавца вместе со структурой Product.
    * @dev
    * - Public view.
    * - Возвращает все товары продавца.
    */
    function getProductsBySellerFull() external view returns (Product[] memory) {
        require(inviteNFT.isSeller(msg.sender), "Not a seller");

        uint256[] memory sellerProductIds = productsBySeller[msg.sender];
        Product[] memory sellerProducts = new Product[](sellerProductIds.length);
        for (uint256 i = 0; i < sellerProductIds.length; i++) {
            sellerProducts[i] = products[sellerProductIds[i]];
        }
        return sellerProducts;
    }

}

